import { signal, delegate } from 'kerfjs';
import type { SafeHtml } from 'kerfjs';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { Inbox, Folder, Plus, Settings } from 'lucide';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/layout.css';
import './navigation.css';

type Route = 'inbox' | 'drafts' | 'projects';
export function mountNavigation(root: HTMLElement, paint: (content: SafeHtml) => void, actions: { navigate(route: Route): void; addProject(): void; settings(): void }) {
  const selected = signal<Route>('inbox');
  const render = () => paint(<aside class="app-navigation kui-layout">
    <nav class="kui-sidebar kui-scroll-owner" aria-label="Workspace navigation">
      <section class="kui-sidebar-section" aria-label="Workspace">
        <MenuHeader label="Workspace" />
        <MenuItem action="navigate" itemId="inbox" label="Inbox" icon={<LucideIcon icon={Inbox} name="inbox" />} selected={selected.value === 'inbox'} trailing={<span aria-label="12 unread items">12</span>} />
        <MenuItem action="navigate" itemId="drafts" label="Drafts" selected={selected.value === 'drafts'} />
      </section>
      <section class="kui-sidebar-section" aria-label="Projects">
        <MenuHeader label="Projects" />
        <MenuItem action="navigate" itemId="projects" label="Design system rollout" icon={<LucideIcon icon={Folder} name="folder" />} selected={selected.value === 'projects'} multiline />
        <MenuItem action="navigate" itemId="archive" label="Archived — administrator access required" disabled multiline />
        <div class="kui-sidebar-surface"><strong>Workspace summary</strong><p>3 active projects. Next team review is Friday.</p></div>
      </section>
    </nav>
    <footer class="app-navigation__footer"><Toolbar label="Sidebar actions" divider={false}
      leading={<ToolbarControlGroup appearance="borderless" single><button type="button" data-action="add-project" aria-label="Add project"><LucideIcon icon={Plus} name="plus" /></button></ToolbarControlGroup>}
      trailing={<ToolbarControlGroup appearance="borderless" single><button type="button" data-action="settings" aria-label="Workspace settings"><LucideIcon icon={Settings} name="settings" /></button></ToolbarControlGroup>} /></footer>
  </aside>);
  const dispose = delegate(root, 'click', '[data-action]', (_event, element) => {
    if (element.dataset.action === 'add-project') return actions.addProject();
    if (element.dataset.action === 'settings') return actions.settings();
    if (element.dataset.action !== 'navigate') return;
    const id = element.dataset.itemId;
    if (id !== 'inbox' && id !== 'drafts' && id !== 'projects') return;
    selected.value = id; render(); actions.navigate(id);
  });
  render();
  return { dispose, select(route: Route) { selected.value = route; render(); } };
}

