.app-navigation { display: grid; grid-template-rows: minmax(0, 1fr) auto; height: 100%; min-height: 0; min-width: 0; color: var(--kui-color-text); background: var(--kui-color-surface); }
.app-navigation .kui-sidebar { overscroll-behavior: contain; }
.app-navigation__footer { border-block-start: 1px solid var(--kui-color-border); }
.app-navigation p { margin-block: var(--kui-space-xs) 0; overflow-wrap: anywhere; }
